/* English Reader service worker — generated by scripts/make-sw.mjs (do not edit dist/sw.js by hand).
 * Precaches the whole app shell + every article / dictionary shard, so the site works offline.
 * All URLs are resolved against the SW scope, so it works at the site root and under a GitHub Pages sub-path. */
const VERSION = '__VERSION__';
const CACHE = 'english-reader-' + VERSION;
const FILES = __FILES__;

const abs = (rel) => new URL(rel, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(FILES.map((f) => new Request(abs(f), { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('english-reader-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch (e) {
        if (req.mode === 'navigate') {
          const shell = await cache.match(abs('index.html'));
          if (shell) return shell;
        }
        throw e;
      }
    }),
  );
});
